import numpy as np
from numba import njit


@njit(cache=True)
def _auction(cost, n, eps_min):
    """Solve the linear assignment problem via the forward auction algorithm
    with epsilon-scaling. Returns assign[j] = row assigned to column j."""
    price = np.zeros(n)
    assign = np.full(n, -1)

    maxc = 0.0
    for i in range(n):
        for j in range(n):
            c = cost[i, j]
            if c > maxc:
                maxc = c

    eps = maxc
    while eps > eps_min:
        row_assigned = np.zeros(n, dtype=np.int64)
        for j in range(n):
            if assign[j] >= 0:
                row_assigned[assign[j]] = 1
        unassigned = []
        for i in range(n):
            if row_assigned[i] == 0:
                unassigned.append(i)

        while len(unassigned) > 0:
            i = unassigned.pop()
            best_val = -1e300
            best_j = -1
            second_val = -1e300
            for j in range(n):
                v = cost[i, j] - price[j]
                if v > best_val:
                    second_val = best_val
                    best_val = v
                    best_j = j
                elif v > second_val:
                    second_val = v
            bid = best_val - second_val + eps
            price[best_j] += bid
            if assign[best_j] >= 0:
                unassigned.append(assign[best_j])
            assign[best_j] = i

        eps = eps / 2.0

    return assign


class Solver:
    def solve(self, problem, **kwargs):
        a = problem["source_weights"]
        b = problem["target_weights"]
        M = problem["cost_matrix"]

        n = len(a)
        m = len(b)

        # Uniform weights: the optimal transport plan is a permutation matrix
        # scaled by the (uniform) weight, i.e. a linear assignment problem.
        if n == m and np.allclose(a, b) and np.allclose(a, a[0]):
            w = float(a[0])
            cost = np.ascontiguousarray(M, dtype=np.float64)
            assign = _auction(cost, n, 1e-9)
            G = np.zeros((n, m), dtype=np.float64)
            for j in range(n):
                G[assign[j], j] = w
            return {"transport_plan": G}

        # General fallback: use the reference solver.
        from reference import Task
        return Task().solve(problem)

